parameters.jsCode:
// Collect all product results (may be multiple from Postgres)
const allItems = $input.all();
const parentData = $('Workflow Input').item?.json ?? {};

// Merge all fetched products into a single context for the AI
const products = allItems.map(item => item.json);
const inStock  = products.filter(p => p.stock > 0);

// Pass through to AI generation node
return [{
  json: {
    products_json:  JSON.stringify(products),
    in_stock_count: inStock.length,
    has_products:   products.length > 0,
    // Forward classifier fields
    business_id:    parentData.business_id,
    business_name:  parentData.business_name,
    intent:         parentData.intent,
    language:       parentData.language,
    chatId:         parentData.chatId,
    phoneNumber:    parentData.phoneNumber,
    messageText:    parentData.messageText,
    discount_json:  'null',
    pricing_json:   'null'
  }
}];

// Out-of-stock path — still generate a reply but note unavailability
const parentData = $('Workflow Input').item?.json ?? {};

return [{
  json: {
    products_json:  JSON.stringify([{ name: 'Item', stock: 0, description: 'Currently out of stock' }]),
    in_stock_count: 0,
    has_products:   false,
    business_id:    parentData.business_id,
    business_name:  parentData.business_name,
    intent:         parentData.intent,
    language:       parentData.language,
    chatId:         parentData.chatId,
    phoneNumber:    parentData.phoneNumber,
    messageText:    parentData.messageText,
    discount_json:  'null',
    pricing_json:   'null'
  }
}];

// Parse Gemini's text response
const aiText = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text ?? $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
const ctx     = $('Prepare AI Input').item?.json ?? $('Out of Stock Path').item?.json ?? {};

return [{
  json: {
    replyText:  aiText.trim(),
    chatId:     ctx.chatId,
    business_id: ctx.business_id,
    phoneNumber: ctx.phoneNumber,
    hasImage:   (JSON.parse(ctx.products_json ?? '[]')[0]?.image_url?.length > 0)
                  && ctx.in_stock_count > 0,
    imageUrl:   JSON.parse(ctx.products_json ?? '[]')[0]?.image_url ?? null
  }
}];

parameters.jsonBody:
={{ JSON.stringify({ contents: [{ parts: [{ text: `You are ${$json.business_name ?? ""}'s friendly WhatsApp sales assistant. Reply in the customer's language (${$json.language ?? ""}).

Tone: warm, concise, like a helpful shop assistant — not corporate, not robotic. Use at most 1–2 relevant emoji.

You are given:
- Customer intent: ${$json.intent ?? ""}
- Matched product(s): ${$json.products_json ?? ""}
- Applicable discount (if any): ${$json.discount_json ?? ""}
- Order total (bulk orders only): ${$json.pricing_json ?? ""}

Format rules:
- Keep replies under 200 words.
- Always end with one clear next step.
- Never state a price not in the data you were given.
- If no matching product found, say so honestly and offer to connect them with the team.\n\nCustomer Message: ${$json.messageText ?? ""}` }] }] }) }}
